# Build grid with all rotations
top_right = [[5, 2, 2, 7, 3, 2], [2, 2, 2, 2, 2, 9], [2, 5, 1, 3, 2, 2], 
             [2, 6, 7, 2, 6, 2], [2, 2, 3, 2, 2, 2], [3, 1, 2, 2, 2, 2]]

def rotate_90cw(grid):
    rows = len(grid)
    return [[grid[rows-1-r][c] for r in range(rows)] for c in range(rows)]

def rotate_180(grid):
    return rotate_90cw(rotate_90cw(grid))

def rotate_270(grid):
    return rotate_90cw(rotate_180(grid))

t_lr = rotate_90cw(top_right)  # For top-left
t_ll = rotate_180(top_right)   # For bottom-left
t_l = rotate_270(top_right)    # For bottom-right

print("TR → TL (90°):", t_lr)
print("TR → BL (180°):", t_ll)
print("TR → BR (270°):", t_l)

# Build the output grid
output = [[2]*13 for _ in range(13)]
for r in range(6):
    for c in range(6):
        output[r][c] = t_lr[r][c]          # Top-left
        output[r][12-c] = top_right[r][c]  # Top-right (but this is wrong - should be direct copy)

# Let me re-think. Top-right position is cols 7-12. Position (r, c) in quarter grid maps to (r, 7+c) in full grid.
# So top-right actual is: output[r][7+c] = top_right[r][c] for c in 0..5

for r in range(6):
    for c in range(6):
        output[r][c] = t_lr[r][c]                  # Top-left quadrant
        output[r][7+c] = top_right[r][c]           # Top-right quadrant
        output[7+r][c] = t_ll[r][c]                 # Bottom-left quadrant
        output[7+r][7+c] = t_l[r][c]                # Bottom-right quadrant

print("\nBuilt output grid:")
for row in output:
    print(row)

# Build grid properly with separators
top_right = [[5, 2, 2, 7, 3, 2], [2, 2, 2, 2, 2, 9], [2, 5, 1, 3, 2, 2], 
             [2, 6, 7, 2, 6, 2], [2, 2, 3, 2, 2, 2], [3, 1, 2, 2, 2, 2]]

def rotate_90cw(grid):
    rows = len(grid)
    return [[grid[rows-1-r][c] for r in range(rows)] for c in range(rows)]

t_lr = rotate_90cw(top_right)  # Top-left
t_ll = rotate_180(top_right)   # Bottom-left
t_l = rotate_270(top_right)    # Bottom-right

# Create 13x13 grid with 4-separator
output = [[0]*13 for _ in range(13)]

# Fill separators
for c in range(13): output[6][c] = 4
for r in range(13): output[r][6] = 4

# Fill top-left: rows 0-5, cols 0-5
for r in range(6):
    for c in range(6):
        output[r][c] = t_lr[r][c]

# Fill top-right: rows 0-5, cols 7-12
for r in range(6):
    for c in range(6):
        output[r][7+c] = top_right[r][c]

# Fill bottom-left: rows 7-12, cols 0-5
for r in range(6):
    for c in range(6):
        output[7+r][c] = t_ll[r][c]

# Fill bottom-right: rows 7-12, cols 7-12  
for r in range(6):
    for c in range(6):
        output[7+r][7+c] = t_l[r][c]

print("Grid with all quadrants filled:")
for row in output:
    print(row)
